Rules.InvariantScript:
ForAll(
    selectedSkills As q,
    Patch(
        UserQualifications,
        Defaults(UserQualifications),
        {
            UserId: SignUpForm.LastSubmit.ID,
            QualificationId:
                LookUp(
                    Qualifications,
                    Title = q.Title
                ).ID
        }
    )
);

Notify("Sign up successful, please login.", NotificationType.Success);

ResetForm(SignUpForm);
Navigate(LoginScreen);

If(
    !SignUpForm.Valid,
    Notify("Please complete all required fields.", NotificationType.Error),

    If(
        !IsMatch(
            SignUpForm.Updates.Email,
            "^[^@\s]+@[^@\s]+\.[^@\s]+$"
        ),

        Notify("Please enter a valid email address.", NotificationType.Error),


            // ✅ VERY IMPORTANT: capture selected skills BEFORE submit
            Set(
                selectedSkills,
                cmbSkills.SelectedItems
            );

            SubmitForm(SignUpForm)
        )
    )

ControlPropertyState.AutoRuleBindingString:
If(
    !IsMatch(
        InputNewEmail.Text,
        "^[^@\s]+@[^@\s]+\.[^@\s]+$"
    ),

    /* Invalid email */
    Notify(
        "Please enter a valid email address.",
        NotificationType.Error
    ),

    /* Email format OK */
    If(
        !IsBlank(LookUp(Users, Email = InputNewEmail.Text)),

        /* Email already exists */
        Notify(
            "An account with this email already exists.",
            NotificationType.Error
        ),

        /* Create new user */
        Patch(
            Users,
            Defaults(Users),
            {
                FirstName: InputFirstName.Text,
                LastName: InputLastName.Text,
                Email: InputNewEmail.Text,
                Password: InputNewPassword.Text,
                UserType: { Value: "Volunteer" },
                HoursWorked: 0
            }
        );

        Notify(
            "Sign up successful, please login to your account",
            NotificationType.Success
        );

        Reset(InputFirstName);
        Reset(InputLastName);
        Reset(InputNewEmail);
        Reset(InputNewPassword);

        Navigate(LoginScreen)
    )
);
